function extractCodeFromResponse(response: string): string {
  // Try to find a fenced code block (```js, ```javascript, ```typescript, etc.)
  const fencedMatch = response.match(
    /```(?:javascript|js|typescript|ts|node)?\n?([\s\S]*?)```/,
  );
  if (fencedMatch) return fencedMatch[1].trim();

  // Try inline code as a fallback
  const inlineMatch = response.match(/`([^`\n]+)`/);
  if (inlineMatch && inlineMatch[1].includes(";")) return inlineMatch[1];

  // Return the raw response — maybe the LLM returned code directly
  return response.trim();
}

