    // Authenticate before doing anything else
    const authHeader = request.headers.get("Authorization");
    if (!authHeader?.startsWith("Bearer ")) {
      return new Response("Unauthorized", {
        status: 401,
        headers: { "WWW-Authenticate": "Bearer" },
      });
    }

    const token = authHeader.slice(7);
    const userId = await validateToken(token, env);
    if (!userId) {
      return new Response("Invalid or expired token", { status: 401 });
    }

    // Each user gets their own isolated sandbox — they can only affect their own
    const sandbox = getSandbox(env.Sandbox, `user-${userId}`);

    const url = new URL(request.url);

    if (url.pathname === "/code" && request.method === "POST") {
      const { code } = (await request.json()) as { code: string };
      const ctx = await sandbox.createCodeContext({ language: "javascript" });
      const result = await sandbox.runCode(code, { context: ctx });

      return Response.json({
        success: result.code === 0,
        stdout: result.logs.stdout,
        error: result.error,
      });
    }

    return new Response("Not found", { status: 404 });
  },
};

